#include <bits/stdc++.h>
using namespace std;

#define pii pair<int,int>
#define mp make_pair
#define inf 100000000
#define MAXN 6000

namespace flow {
    vector<int> v[MAXN], rev[MAXN], cost[MAXN], cap[MAXN];

    void add_edge(int x, int y, int c, int w) {
        rev[x].push_back((int)v[y].size());
        rev[y].push_back((int)v[x].size());
        v[x].push_back(y);
        v[y].push_back(x);
        cost[x].push_back(w);
        cost[y].push_back(-w);
        cap[x].push_back(c);
        cap[y].push_back(0);
    }

    int dist[MAXN], visited[MAXN], pre_x[MAXN], pre_i[MAXN];

    void spfa(int s) {
        fill(dist, dist + MAXN, 0x3f3f3f3f);
        fill(visited, visited + MAXN, 0);
        pre_x[s] = -1;
        queue<int> q;
        q.push(s);
        dist[s] = 0;
        visited[s] = 1;

        while (!q.empty()) {
            int x = q.front(); q.pop(); visited[x] = 0;
            for (size_t i = 0; i < v[x].size(); ++i) {
                int y = v[x][i];
                int new_dist = dist[x] + cost[x][i];
                if (dist[y] > new_dist && cap[x][i]) {
                    dist[y] = new_dist;
                    pre_x[y] = x;
                    pre_i[y] = i;
                    if (!visited[y]) { visited[y] = 1; q.push(y); }
                }
            }
        }
    }

    int total_flow = 0;

    int dfs(int x, int flow) {
        if (pre_x[x] == -1) return flow;
        int y = x; x = pre_x[y]; int i = pre_i[y], j = rev[x][i];
        int f = dfs(x, min(flow, cap[x][i]));
        cap[x][i] -= f;
        cap[y][j] += f;
        return f;
    }

    pair<int,int> solve(int s, int t) {
        int ans = 0, total_cost = 0;
        while (true) {
            spfa(s);
            if (dist[t] > 1e9) break;
            int f = dfs(t, inf);
            total_cost += f * dist[t];
            ans += f;
        }
        return mp(ans, total_cost);
    }
}

int main() {
    int n, m, s = MAXN - 1, t = MAXN - 2;
    int k, c, d;
    cin >> n >> m >> k >> c >> d;

    auto get_node = [](int x, int t) { return t * 52 - 52 + x; };

    for (int i = 0; i < k; ++i) {
        int x; cin >> x;
        flow::add_edge(s, get_node(x, 1), 1, 0);
    }

    int original_k = k;
    for (int i = 0; i < m; ++i) {
        int x, y; cin >> x >> y;
        for (int t = 1; t < 100; ++t) {
            for (int j = 1; j <= original_k; ++j) {
                flow::add_edge(get_node(x, t), get_node(y, t + 1), 1, d * (j + j - 1));
            }
        }
        swap(x, y);
        for (int t = 1; t < 100; ++t) {
            for (int j = 1; j <= original_k; ++j) {
                flow::add_edge(get_node(x, t), get_node(y, t + 1), 1, d * (j + j - 1));
            }
        }
    }

    for (int i = 1; i < 100; ++i) {
        for (int j = 1; j <= n; ++j) {
            flow::add_edge(get_node(j, i), get_node(j, i + 1), inf, 0);
        }
        flow::add_edge(get_node(1, i), t, inf, c * (i - 1));
    }

    cout << flow::solve(s, t).second;
    return 0;
}
